Layout.Stylesheet:
body { margin: 0; font-size: 9pt; }
div { margin: 5pt; padding: 5pt; border-style: solid; border-color: blue; }
.px1 { border-width: 1px; }
.pt1 { border-width: 1pt; }
.pt2 { border-width: 2pt; }
.pt3 { border-width: 3pt; }
.mixed { border-top-width: 1pt; border-right-width: 2pt; border-bottom-width: 3pt; border-left-width: 4pt; }
